function guide(id, look, when, rule) {
  if (SPECIES[id]) SPECIES[id].guide = { look, when, rule };
}

guide("bandicoot", "灰褐，鼻子又长又尖，耳朵圆，夜里在草里拱土。", "黄昏到入夜，北头在步道边。", "不追，不开闪光灯，不离开步道去找窝。");
guide("honeyeater", "黑白花纹，眼后一块黄，叫声尖。", "清晨和午前，开花的灌丛上。", "人停在步道上，不摇花。");
guide("wattlebird", "比吸蜜鸟大，喉下有肉垂，灰褐带细纹。", "清晨，有花的灌丛。", "不靠近巢，拍几张就让开。");
guide("whale", "座头鲸喷气低而宽，胸鳍很长。", "五月到十一月，从崖上往外看。", "人留在岸上。船要保持距离：成鲸 100 米，有幼鲸 300 米。");
guide("echidna", "一身刺，鼻子尖，走路慢。", "白天，步道边的土和倒木。", "不捡起来，不挡它的路。");
guide("lyrebird", "褐灰色，尾羽很长，会学别的声音。", "清晨，潮湿的林下。", "人停在步道上，不跟着它进林。");
guide("blackcockatoo", "黑色，尾羽有黄或红的斑，叫声粗。", "清晨和黄昏，飞过或停在桉树上。", "不靠近正在吃东西的树，不放录音。");
guide("kingfisher", "蓝绿背，白喉，停在伸出水面的枝上。", "清晨，静水边。", "人留在岸上，不赶它飞。");
guide("goanna", "大蜥蜴，灰褐带斑，舌头分叉。", "上午晒太阳之后。", "不喂，不挡路，保持几米。");
guide("wallaby", "灰褐，比袋鼠小，黎明在草地。", "开门后的第一小时。", "人停下。它们退进灌丛就不要跟。");
guide("seaeagle", "白头白腹，翼下很宽，在崖上盘。", "有风的白天。", "不靠近巢，从观景台拍。");
guide("bowerbird", "缎蓝亭鸟的雄鸟深蓝，亭是用树枝搭的。", "清晨，林缘。", "不碰它的亭，不放蓝色的东西引它。");
guide("ganggang", "雄鸟红头，雌鸟全身灰绿带横斑。", "清晨，山里的桉树。", "不放录音，不离开步道。");
guide("rosella", "红头或绯红，翅膀有蓝和黄。", "清晨到午前，开阔的林地。", "不喂。");
guide("wedgetail", "澳洲最大的鹰，楔形尾。", "有上升气流的白天。", "不靠近巢。");
guide("spoonbill", "白，嘴像勺子，在浅水里左右扫。", "退潮或清晨的浅滩。", "人留在栈道上，不赶它们起飞。");
guide("swan", "黑天鹅，红嘴，在开阔水面。", "一天里都可能在。", "不喂，不下水靠近。");
guide("groper", "蓝石斑，嘴唇厚，在岩礁边。", "晴天的上午，水清的时候。", "Action 4 慢慢过，不追，不喂。");
guide("bristlebird", "褐，尾巴长，藏在浓密灌丛里，很少飞起来。", "清晨，能听见比能看见多。", "人留在栈道上。这是受胁鸟，不离开步道找。");
guide("groundparrot", "绿，尾巴长，几乎不飞，只在灌丛里叫。", "黎明和黄昏，听见就停。", "人留在栈道上，不进灌丛。");
guide("dolphin", "灰，背鳍弯，成小群。", "从崖上或船上，白天。", "船保持 50 米，有幼豚 150 米。游泳的人保持 30 米。");
guide("fantail", "灰，尾巴张开像扇子，跟着人走是在吃惊起的虫。", "林间白天。", "不用食物引它。");
guide("seadragon", "草海龙身上有叶状附肢，贴着海藻。", "水清的白天，岩礁和海藻里。", "一次慢速经过就离开，不追，不用闪光灯。");
guide("dragon", "东部水龙，灰绿，沿下颌有一条浅色。", "上午晒太阳，溪边的石头上。", "不喂，不下水赶。");
guide("owl", "猛鸮很大，胸前有 V 形斑，黄昏叫。", "黄昏，在步道上听。", "不放录音，不找它睡觉的树。");
guide("platypus", "扁嘴，低低贴着水面。", "黎明，静水边。", "人留在岸上，灯不要照水面，不找洞穴。");
guide("oystercatcher", "黑白，嘴橙红又长，在岩石和沙滩上。", "退潮。", "不靠近正在孵蛋或带着幼鸟的。");
guide("fairywren", "雄鸟亮蓝，雌鸟褐，尾巴翘着。", "清晨，灌丛下层。", "不摇灌丛。");
guide("osprey", "白头，眼上有深色过眼线，在水面上停。", "白天，河口和海岸。", "不靠近巢。");
guide("cuttlefish", "澳洲巨乌贼，皮肤会变色。", "水清的白天，岩礁边。", "一次慢速经过，不追，不抓。");
guide("octopus", "忧郁章鱼，红褐，藏在石缝。", "水清的白天。", "不翻石头。");
guide("flyingfox", "灰头狐蝠，白天挂在树上，黄昏飞出。", "黄昏看飞出的方向。", "不进营地，不吵它们。植物园的营地不是目标。");
guide("rockwarbler", "岩莺，褐灰，尾巴翘，在砂岩上跳。", "清晨，砂岩步道边。", "人留在步道上。");
guide("heron", "白脸鹭，灰身白脸，黄腿。", "浅水和潮间带。", "不赶它飞。");
guide("shorebird", "迁徙涉禽里的一种。照片是斑尾塍鹬，只代表这一类，不是每一种。", "退潮，在泥滩远处。", "人留在栈道上。不靠近栖息的群。精确位置不放进导出的文件。");
guide("glowworm", "萤火虫幼虫，黑暗里是蓝色的点。", "洞里全黑的时候。", "不用白光直照，不离开规定的步道。");

