function ensureSpecies(id, name, sci, realm, sensitive) {
  if (typeof SPECIES === "undefined") return;
  if (!SPECIES[id]) SPECIES[id] = { name: name, sci: sci, realm: realm, sensitive: !!sensitive };
  else {
    if (!SPECIES[id].realm) SPECIES[id].realm = realm;
    if (sensitive) SPECIES[id].sensitive = true;
    if (!SPECIES[id].sci && sci) SPECIES[id].sci = sci;
  }
}

function addSeen(id, animal) {
  if (typeof FIELD === "undefined" || !FIELD[id]) return;
  const list = FIELD[id].animals || (FIELD[id].animals = []);
  if (list.some((row) => row.id === animal.id)) return;
  list.push(animal);
}

function addSight(id, animal, rows) {
  if (typeof SIGHTINGS === "undefined" || !rows || !rows.length) return;
  const key = id + "|" + animal;
  if (SIGHTINGS[key] && SIGHTINGS[key].length) return;
  SIGHTINGS[key] = rows.map((row) => {
    const item = { date: row.date, source: row.source };
    if (row.km != null) item.km = row.km;
    return item;
  });
}

