function applyPlaceFauna() {
  [typeof CAMP_AREAS === "undefined" ? null : CAMP_AREAS, typeof BRIEF_PLACES === "undefined" ? null : BRIEF_PLACES].forEach((list) => {
    if (!list) return;
    list.forEach((area) => {
      const row = PLACE_FAUNA[area.id];
      if (!row || area.fauna) return;
      area.fauna = row;
    });
  });
}
if (typeof document !== "undefined") document.addEventListener("DOMContentLoaded", applyPlaceFauna);
